        kd = eval_as_double(z + Shift);
        ki = asuint64(kd) >> 16;
        kd = (double_t)(int32_t)ki;
#else
        /* z - kd is in [-1, 1] in non-nearest rounding modes.  */
        kd = eval_as_double(z + Shift);
        ki = asuint64(kd);
        kd -= Shift;
#endif
        r = __builtin_fma(kd, NegLn2loN, __builtin_fma(kd, NegLn2hiN, x));
