static const lxl_str sl5862 = {.p = sl5862b, .len = 97U, .cap = 0U};
static char sl5863b[83] = "   and write halves are owned apart is closed when the second half is released. */";
static const lxl_str sl5863 = {.p = sl5863b, .len = 82U, .cap = 0U};
static char sl5864b[50] = "static void rt_hup_seen(int64_t fd, uint32_t e) {";
static const lxl_str sl5864 = {.p = sl5864b, .len = 49U, .cap = 0U};
static char sl5865b[95] = "    uint8_t g = (uint8_t)(((e & EPOLLRDHUP) \077 1 : 0) | ((e & (EPOLLHUP | EPOLLERR)) \077 2 : 0));";
static const lxl_str sl5865 = {.p = sl5865b, .len = 94U, .cap = 0U};
