static const lxl_str sl5867 = {.p = sl5867b, .len = 32U, .cap = 0U};
static char sl5868b[77] = "    if (t && (g & rt_fds[fd].hupmode)) { rt_fds[fd].hup = 0; rt_cancel(t); }";
