static char sl5869b[97] = "/* Arms (mode 1: a half-close, 2: a hangup, 3: either) or disarms (0) the hangup cancellation of";
static const lxl_str sl5869 = {.p = sl5869b, .len = 96U, .cap = 0U};
static char sl5870b[96] = "   the running task on socket fd: 1 when the peer had already gone (the task is cancelled now),";
static const lxl_str sl5870 = {.p = sl5870b, .len = 95U, .cap = 0U};
static char sl5871b[96] = "   else 0. A half-close already pending when mode 1 or 3 is armed does not count: the peer sent";
