static const lxl_str sl7006 = {.p = sl7006b, .len = 28U, .cap = 0U};
static char sl7007b[54] = "/* origin: FreeBSD /usr/src/lib/msun/src/s_expm1.c */";
static const lxl_str sl7007 = {.p = sl7007b, .len = 53U, .cap = 0U};
static char sl7008b[56] = " * ====================================================";
static const lxl_str sl7008 = {.p = sl7008b, .len = 55U, .cap = 0U};
static char sl7009b[69] = " * Copyright (C) 1993 by Sun Microsystems, Inc. All rights reserved.";
static const lxl_str sl7009 = {.p = sl7009b, .len = 68U, .cap = 0U};
static char sl7010b[59] = " * Developed at SunPro, a Sun Microsystems, Inc. business.";
static const lxl_str sl7010 = {.p = sl7010b, .len = 58U, .cap = 0U};
static char sl7011b[56] = " * Permission to use, copy, modify, and distribute this";
static const lxl_str sl7011 = {.p = sl7011b, .len = 55U, .cap = 0U};
static char sl7012b[57] = " * software is freely granted, provided that this notice";
static const lxl_str sl7012 = {.p = sl7012b, .len = 56U, .cap = 0U};
static char sl7013b[17] = " * is preserved.";
static const lxl_str sl7013 = {.p = sl7013b, .len = 16U, .cap = 0U};
static char sl7014b[12] = "/* expm1(x)";
static const lxl_str sl7014 = {.p = sl7014b, .len = 11U, .cap = 0U};
static char sl7015b[51] = " * Returns exp(x)-1, the exponential of x minus 1.";
static const lxl_str sl7015 = {.p = sl7015b, .len = 50U, .cap = 0U};
static char sl7016b[10] = " * Method";
static const lxl_str sl7016 = {.p = sl7016b, .len = 9U, .cap = 0U};
static char sl7017b[28] = " *   1. Argument reduction:";
static const lxl_str sl7017 = {.p = sl7017b, .len = 27U, .cap = 0U};
static char sl7018b[48] = " *      Given x, find r and integer k such that";
static const lxl_str sl7018 = {.p = sl7018b, .len = 47U, .cap = 0U};
static char sl7019b[58] = " *               x = k*ln2 + r,  |r| <= 0.5*ln2 ~ 0.34658";
static const lxl_str sl7019 = {.p = sl7019b, .len = 57U, .cap = 0U};
static char sl7020b[64] = " *      Here a correction term c will be computed to compensate";
static const lxl_str sl7020 = {.p = sl7020b, .len = 63U, .cap = 0U};
static char sl7021b[64] = " *      the error in r when rounded to a floating-point number.";
static const lxl_str sl7021 = {.p = sl7021b, .len = 63U, .cap = 0U};
static char sl7022b[65] = " *   2. Approximating expm1(r) by a special rational function on";
static const lxl_str sl7022 = {.p = sl7022b, .len = 64U, .cap = 0U};
static char sl7023b[34] = " *      the interval [0,0.34658]:";
static const lxl_str sl7023 = {.p = sl7023b, .len = 33U, .cap = 0U};
static char sl7024b[14] = " *      Since";
static const lxl_str sl7024 = {.p = sl7024b, .len = 13U, .cap = 0U};
static char sl7025b[63] = " *          r*(exp(r)+1)/(exp(r)-1) = 2+ r^2/6 - r^4/360 + ...";
static const lxl_str sl7025 = {.p = sl7025b, .len = 62U, .cap = 0U};
static char sl7026b[29] = " *      we define R1(r*r) by";
static const lxl_str sl7026 = {.p = sl7026b, .len = 28U, .cap = 0U};
static char sl7027b[57] = " *          r*(exp(r)+1)/(exp(r)-1) = 2+ r^2/6 * R1(r*r)";
static const lxl_str sl7027 = {.p = sl7027b, .len = 56U, .cap = 0U};
static char sl7028b[17] = " *      That is,";
static const lxl_str sl7028 = {.p = sl7028b, .len = 16U, .cap = 0U};
static char sl7029b[58] = " *          R1(r**2) = 6/r *((exp(r)+1)/(exp(r)-1) - 2/r)";
static const lxl_str sl7029 = {.p = sl7029b, .len = 57U, .cap = 0U};
static char sl7030b[61] = " *                   = 6/r * ( 1 + 2.0*(1/(exp(r)-1) - 1/r))";
static const lxl_str sl7030 = {.p = sl7030b, .len = 60U, .cap = 0U};
static char sl7031b[64] = " *                   = 1 - r^2/60 + r^4/2520 - r^6/100800 + ...";
static const lxl_str sl7031 = {.p = sl7031b, .len = 63U, .cap = 0U};
static char sl7032b[66] = " *      We use a special Remez algorithm on [0,0.347] to generate";
static const lxl_str sl7032 = {.p = sl7032b, .len = 65U, .cap = 0U};
static char sl7033b[63] = " *      a polynomial of degree 5 in r*r to approximate R1. The";
static const lxl_str sl7033 = {.p = sl7033b, .len = 62U, .cap = 0U};
static char sl7034b[66] = " *      maximum error of this polynomial approximation is bounded";
static const lxl_str sl7034 = {.p = sl7034b, .len = 65U, .cap = 0U};
static char sl7035b[35] = " *      by 2**-61. In other words,";
static const lxl_str sl7035 = {.p = sl7035b, .len = 34U, .cap = 0U};
static char sl7036b[71] = " *          R1(z) ~ 1.0 + Q1*z + Q2*z**2 + Q3*z**3 + Q4*z**4 + Q5*z**5";
static const lxl_str sl7036 = {.p = sl7036b, .len = 70U, .cap = 0U};
static char sl7037b[50] = " *      where   Q1  =  -1.6666666666666567384E-2,";
static const lxl_str sl7037 = {.p = sl7037b, .len = 49U, .cap = 0U};
static char sl7038b[50] = " *              Q2  =   3.9682539681370365873E-4,";
static const lxl_str sl7038 = {.p = sl7038b, .len = 49U, .cap = 0U};
static char sl7039b[50] = " *              Q3  =  -9.9206344733435987357E-6,";
static const lxl_str sl7039 = {.p = sl7039b, .len = 49U, .cap = 0U};
static char sl7040b[50] = " *              Q4  =   2.5051361420808517002E-7,";
static const lxl_str sl7040 = {.p = sl7040b, .len = 49U, .cap = 0U};
static char sl7041b[50] = " *              Q5  =  -6.2843505682382617102E-9;";
static const lxl_str sl7041 = {.p = sl7041b, .len = 49U, .cap = 0U};
static char sl7042b[28] = " *              z   =  r*r,";
static const lxl_str sl7042 = {.p = sl7042b, .len = 27U, .cap = 0U};
static char sl7043b[30] = " *      with error bounded by";
static const lxl_str sl7043 = {.p = sl7043b, .len = 29U, .cap = 0U};
static char sl7044b[53] = " *          |                  5           |     -61";
static const lxl_str sl7044 = {.p = sl7044b, .len = 52U, .cap = 0U};
static char sl7045b[50] = " *          | 1.0+Q1*z+...+Q5*z   -  R1(z) | <= 2";
static const lxl_str sl7045 = {.p = sl7045b, .len = 49U, .cap = 0U};
static char sl7046b[45] = " *          |                              |";
static const lxl_str sl7046 = {.p = sl7046b, .len = 44U, .cap = 0U};
static char sl7047b[62] = " *      expm1(r) = exp(r)-1 is then computed by the following";
static const lxl_str sl7047 = {.p = sl7047b, .len = 61U, .cap = 0U};
static char sl7048b[69] = " *      specific way which minimize the accumulation rounding error:";
static const lxl_str sl7048 = {.p = sl7048b, .len = 68U, .cap = 0U};
static char sl7049b[39] = " *                             2     3";
static const lxl_str sl7049 = {.p = sl7049b, .len = 38U, .cap = 0U};
static char sl7050b[64] = " *                            r     r    [ 3 - (R1 + R1*r/2)  ]";
static const lxl_str sl7050 = {.p = sl7050b, .len = 63U, .cap = 0U};
static char sl7051b[64] = " *            expm1(r) = r + --- + --- * [--------------------]";
static const lxl_str sl7051 = {.p = sl7051b, .len = 63U, .cap = 0U};
static char sl7052b[64] = " *                            2     2    [ 6 - r*(3 - R1*r/2) ]";
static const lxl_str sl7052 = {.p = sl7052b, .len = 63U, .cap = 0U};
static char sl7053b[66] = " *      To compensate the error in the argument reduction, we use";
static const lxl_str sl7053 = {.p = sl7053b, .len = 65U, .cap = 0U};
static char sl7054b[55] = " *              expm1(r+c) = expm1(r) + c + expm1(r)*c";
static const lxl_str sl7054 = {.p = sl7054b, .len = 54U, .cap = 0U};
static char sl7055b[48] = " *                         ~ expm1(r) + c + r*c";
static const lxl_str sl7055 = {.p = sl7055b, .len = 47U, .cap = 0U};
static char sl7056b[64] = " *      Thus c+r*c will be added in as the correction terms for";
static const lxl_str sl7056 = {.p = sl7056b, .len = 63U, .cap = 0U};
static char sl7057b[65] = " *      expm1(r+c). Now rearrange the term to avoid optimization";
static const lxl_str sl7057 = {.p = sl7057b, .len = 64U, .cap = 0U};
static char sl7058b[18] = " *      screw up:";
static const lxl_str sl7058 = {.p = sl7058b, .len = 17U, .cap = 0U};
static char sl7059b[72] = " *                      (      2                                    2 )";
static const lxl_str sl7059 = {.p = sl7059b, .len = 71U, .cap = 0U};
static char sl7060b[72] = " *                      ({  ( r    [ R1 -  (3 - R1*r/2) ]  )  }    r  )";
static const lxl_str sl7060 = {.p = sl7060b, .len = 71U, .cap = 0U};
static char sl7061b[72] = " *       expm1(r+c)~r - ({r*(--- * [--------------------]-c)-c} - --- )";
static const lxl_str sl7061 = {.p = sl7061b, .len = 71U, .cap = 0U};
static char sl7062b[72] = " *                      ({  ( 2    [ 6 - r*(3 - R1*r/2) ]  )  }    2  )";
static const lxl_str sl7062 = {.p = sl7062b, .len = 71U, .cap = 0U};
static char sl7063b[72] = " *                      (                                             )";
static const lxl_str sl7063 = {.p = sl7063b, .len = 71U, .cap = 0U};
static char sl7064b[27] = " *                 = r - E";
static const lxl_str sl7064 = {.p = sl7064b, .len = 26U, .cap = 0U};
static char sl7065b[39] = " *   3. Scale back to obtain expm1(x):";
static const lxl_str sl7065 = {.p = sl7065b, .len = 38U, .cap = 0U};
static char sl7066b[29] = " *      From step 1, we have";
static const lxl_str sl7066 = {.p = sl7066b, .len = 28U, .cap = 0U};
static char sl7067b[50] = " *         expm1(x) = either 2^k*[expm1(r)+1] - 1";
static const lxl_str sl7067 = {.p = sl7067b, .len = 49U, .cap = 0U};
static char sl7068b[55] = " *                  = or     2^k*[expm1(r) + (1-2^-k)]";
static const lxl_str sl7068 = {.p = sl7068b, .len = 54U, .cap = 0U};
static char sl7069b[30] = " *   4. Implementation notes:";
static const lxl_str sl7069 = {.p = sl7069b, .len = 29U, .cap = 0U};
static char sl7070b[69] = " *      (A). To save one multiplication, we scale the coefficient Qi";
static const lxl_str sl7070 = {.p = sl7070b, .len = 68U, .cap = 0U};
static char sl7071b[50] = " *           to Qi*2^i, and replace z by (x^2)/2.";
static const lxl_str sl7071 = {.p = sl7071b, .len = 49U, .cap = 0U};
static char sl7072b[65] = " *      (B). To achieve maximum accuracy, we compute expm1(x) by";
static const lxl_str sl7072 = {.p = sl7072b, .len = 64U, .cap = 0U};
static char sl7073b[71] = " *        (i)   if x < -56*ln2, return -1.0, (raise inexact if x!=inf)";
static const lxl_str sl7073 = {.p = sl7073b, .len = 70U, .cap = 0U};
static char sl7074b[35] = " *        (ii)  if k=0, return r-E";
static const lxl_str sl7074 = {.p = sl7074b, .len = 34U, .cap = 0U};
static char sl7075b[46] = " *        (iii) if k=-1, return 0.5*(r-E)-0.5";
static const lxl_str sl7075 = {.p = sl7075b, .len = 45U, .cap = 0U};
static char sl7076b[59] = " *        (iv)  if k=1 if r < -0.25, return 2*((r+0.5)- E)";
static const lxl_str sl7076 = {.p = sl7076b, .len = 58U, .cap = 0U};
static char sl7077b[60] = " *                     else          return  1.0+2.0*(r-E);";
static const lxl_str sl7077 = {.p = sl7077b, .len = 59U, .cap = 0U};
static char sl7078b[70] = " *        (v)   if (k<-2||k>56) return 2^k(1-(E-r)) - 1 (or exp(x)-1)";
static const lxl_str sl7078 = {.p = sl7078b, .len = 69U, .cap = 0U};
static char sl7079b[61] = " *        (vi)  if k <= 20, return 2^k((1-2^-k)-(E-r)), else";
static const lxl_str sl7079 = {.p = sl7079b, .len = 60U, .cap = 0U};
static char sl7080b[43] = " *        (vii) return 2^k(1-((E+2^-k)-r))";
static const lxl_str sl7080 = {.p = sl7080b, .len = 42U, .cap = 0U};
static char sl7081b[18] = " * Special cases:";
static const lxl_str sl7081 = {.p = sl7081b, .len = 17U, .cap = 0U};
static char sl7082b[46] = " *      expm1(INF) is INF, expm1(NaN) is NaN;";
static const lxl_str sl7082 = {.p = sl7082b, .len = 45U, .cap = 0U};
static char sl7083b[31] = " *      expm1(-INF) is -1, and";
static const lxl_str sl7083 = {.p = sl7083b, .len = 30U, .cap = 0U};
static char sl7084b[55] = " *      for finite argument, only expm1(0)=0 is exact.";
static const lxl_str sl7084 = {.p = sl7084b, .len = 54U, .cap = 0U};
static char sl7085b[13] = " * Accuracy:";
static const lxl_str sl7085 = {.p = sl7085b, .len = 12U, .cap = 0U};
static char sl7086b[70] = " *      according to an error analysis, the error is always less than";
static const lxl_str sl7086 = {.p = sl7086b, .len = 69U, .cap = 0U};
static char sl7087b[40] = " *      1 ulp (unit in the last place).";
static const lxl_str sl7087 = {.p = sl7087b, .len = 39U, .cap = 0U};
static char sl7088b[15] = " * Misc. info.";
static const lxl_str sl7088 = {.p = sl7088b, .len = 14U, .cap = 0U};
static char sl7089b[24] = " *      For IEEE double";
static const lxl_str sl7089 = {.p = sl7089b, .len = 23U, .cap = 0U};
static char sl7090b[70] = " *          if x >  7.09782712893383973096e+02 then expm1(x) overflow";
static const lxl_str sl7090 = {.p = sl7090b, .len = 69U, .cap = 0U};
static char sl7091b[14] = " * Constants:";
static const lxl_str sl7091 = {.p = sl7091b, .len = 13U, .cap = 0U};
static char sl7092b[66] = " * The hexadecimal values are the intended ones for the following";
static const lxl_str sl7092 = {.p = sl7092b, .len = 65U, .cap = 0U};
static char sl7093b[64] = " * constants. The decimal values may be used, provided that the";
static const lxl_str sl7093 = {.p = sl7093b, .len = 63U, .cap = 0U};
