static char sl7191b[54] = "/* origin: FreeBSD /usr/src/lib/msun/src/s_log1p.c */";
static const lxl_str sl7191 = {.p = sl7191b, .len = 53U, .cap = 0U};
static char sl7192b[26] = "/* double log1p(double x)";
static const lxl_str sl7192 = {.p = sl7192b, .len = 25U, .cap = 0U};
static char sl7193b[40] = " * Return the natural logarithm of 1+x.";
static const lxl_str sl7193 = {.p = sl7193b, .len = 39U, .cap = 0U};
static char sl7194b[12] = " * Method :";
static const lxl_str sl7194 = {.p = sl7194b, .len = 11U, .cap = 0U};
static char sl7195b[51] = " *   1. Argument Reduction: find k and f such that";
static const lxl_str sl7195 = {.p = sl7195b, .len = 50U, .cap = 0U};
static char sl7196b[43] = " *                      1+x = 2^k * (1+f),";
static const lxl_str sl7196 = {.p = sl7196b, .len = 42U, .cap = 0U};
static char sl7197b[46] = " *         where  sqrt(2)/2 < 1+f < sqrt(2) .";
static const lxl_str sl7197 = {.p = sl7197b, .len = 45U, .cap = 0U};
static char sl7198b[66] = " *      Note. If k=0, then f=x is exact. However, if k!=0, then f";
static const lxl_str sl7198 = {.p = sl7198b, .len = 65U, .cap = 0U};
static char sl7199b[69] = " *      may not be representable exactly. In that case, a correction";
static const lxl_str sl7199 = {.p = sl7199b, .len = 68U, .cap = 0U};
static char sl7200b[63] = " *      term is need. Let u=1+x rounded. Let c = (1+x)-u, then";
static const lxl_str sl7200 = {.p = sl7200b, .len = 62U, .cap = 0U};
static char sl7201b[69] = " *      log(1+x) - log(u) ~ c/u. Thus, we proceed to compute log(u),";
static const lxl_str sl7201 = {.p = sl7201b, .len = 68U, .cap = 0U};
static char sl7202b[46] = " *      and add back the correction term c/u.";
static const lxl_str sl7202 = {.p = sl7202b, .len = 45U, .cap = 0U};
static char sl7203b[61] = " *      (Note: when x > 2**53, one can simply return log(x))";
static const lxl_str sl7203 = {.p = sl7203b, .len = 60U, .cap = 0U};
static char sl7204b[45] = " *   2. Approximation of log(1+f): See log.c";
static const lxl_str sl7204 = {.p = sl7204b, .len = 44U, .cap = 0U};
static char sl7205b[62] = " *   3. Finally, log1p(x) = k*ln2 + log(1+f) + c/u. See log.c";
static const lxl_str sl7205 = {.p = sl7205b, .len = 61U, .cap = 0U};
static char sl7206b[65] = " *      log1p(x) is NaN with signal if x < -1 (including -INF) ;";
static const lxl_str sl7206 = {.p = sl7206b, .len = 64U, .cap = 0U};
static char sl7207b[60] = " *      log1p(+INF) is +INF; log1p(-1) is -INF with signal;";
static const lxl_str sl7207 = {.p = sl7207b, .len = 59U, .cap = 0U};
static char sl7208b[47] = " *      log1p(NaN) is that NaN with no signal.";
static const lxl_str sl7208 = {.p = sl7208b, .len = 46U, .cap = 0U};
static char sl7209b[62] = " * Note: Assuming log() return accurate answer, the following";
static const lxl_str sl7209 = {.p = sl7209b, .len = 61U, .cap = 0U};
static char sl7210b[72] = " *       algorithm can be used to compute log1p(x) to within a few ULP:";
static const lxl_str sl7210 = {.p = sl7210b, .len = 71U, .cap = 0U};
static char sl7211b[25] = " *              u = 1+x;";
static const lxl_str sl7211 = {.p = sl7211b, .len = 24U, .cap = 0U};
static char sl7212b[43] = " *              if(u==1.0) return x ; else";
static const lxl_str sl7212 = {.p = sl7212b, .len = 42U, .cap = 0U};
static char sl7213b[54] = " *                         return log(u)*(x/(u-1.0));";
static const lxl_str sl7213 = {.p = sl7213b, .len = 53U, .cap = 0U};
static char sl7214b[56] = " *       See HP-15C Advanced Functions Handbook, p.193.";
static const lxl_str sl7214 = {.p = sl7214b, .len = 55U, .cap = 0U};
static char sl7215b[62] = "ln2_hi = 6.93147180369123816490e-01,  /* 3fe62e42 fee00000 */";
static const lxl_str sl7215 = {.p = sl7215b, .len = 61U, .cap = 0U};
static char sl7216b[62] = "ln2_lo = 1.90821492927058770002e-10,  /* 3dea39ef 35793c76 */";
static const lxl_str sl7216 = {.p = sl7216b, .len = 61U, .cap = 0U};
static char sl7217b[57] = "Lg1 = 6.666666666666735130e-01,  /* 3FE55555 55555593 */";
static const lxl_str sl7217 = {.p = sl7217b, .len = 56U, .cap = 0U};
