static char sl7274b[55] = "/* ---- musl 1.2.5 src/math/__rem_pio2_large.c ---- */";
static const lxl_str sl7274 = {.p = sl7274b, .len = 54U, .cap = 0U};
static char sl7275b[57] = "/* origin: FreeBSD /usr/src/lib/msun/src/k_rem_pio2.c */";
static const lxl_str sl7275 = {.p = sl7275b, .len = 56U, .cap = 0U};
static char sl7276b[60] = " * Developed at SunSoft, a Sun Microsystems, Inc. business.";
static const lxl_str sl7276 = {.p = sl7276b, .len = 59U, .cap = 0U};
static char sl7277b[36] = " * __rem_pio2_large(x,y,e0,nx,prec)";
static const lxl_str sl7277 = {.p = sl7277b, .len = 35U, .cap = 0U};
static char sl7278b[35] = " * double x[],y[]; int e0,nx,prec;";
static const lxl_str sl7278 = {.p = sl7278b, .len = 34U, .cap = 0U};
static char sl7279b[59] = " * __rem_pio2_large return the last three digits of N with";
static const lxl_str sl7279 = {.p = sl7279b, .len = 58U, .cap = 0U};
static char sl7280b[31] = " *              y = x - N*pi/2";
static const lxl_str sl7280 = {.p = sl7280b, .len = 30U, .cap = 0U};
static char sl7281b[23] = " * so that |y| < pi/2.";
static const lxl_str sl7281 = {.p = sl7281b, .len = 22U, .cap = 0U};
static char sl7282b[70] = " * The method is to compute the integer (mod 8) and fraction parts of";
static const lxl_str sl7282 = {.p = sl7282b, .len = 69U, .cap = 0U};
static char sl7283b[65] = " * (2/pi)*x without doing the full multiplication. In general we";
static const lxl_str sl7283 = {.p = sl7283b, .len = 64U, .cap = 0U};
static char sl7284b[70] = " * skip the part of the product that are known to be a huge integer (";
static const lxl_str sl7284 = {.p = sl7284b, .len = 69U, .cap = 0U};
static char sl7285b[67] = " * more accurately, = 0 mod 8 ). Thus the number of operations are";
static const lxl_str sl7285 = {.p = sl7285b, .len = 66U, .cap = 0U};
static char sl7286b[45] = " * independent of the exponent of the input.";
static const lxl_str sl7286 = {.p = sl7286b, .len = 44U, .cap = 0U};
static char sl7287b[68] = " * (2/pi) is represented by an array of 24-bit integers in ipio2[].";
static const lxl_str sl7287 = {.p = sl7287b, .len = 67U, .cap = 0U};
static char sl7288b[21] = " * Input parameters:";
static const lxl_str sl7288 = {.p = sl7288b, .len = 20U, .cap = 0U};
static char sl7289b[69] = " *      x[]     The input value (must be positive) is broken into nx";
static const lxl_str sl7289 = {.p = sl7289b, .len = 68U, .cap = 0U};
static char sl7290b[70] = " *              pieces of 24-bit integers in double precision format.";
static const lxl_str sl7290 = {.p = sl7290b, .len = 69U, .cap = 0U};
static char sl7291b[71] = " *              x[i] will be the i-th 24 bit of x. The scaled exponent";
static const lxl_str sl7291 = {.p = sl7291b, .len = 70U, .cap = 0U};
static char sl7292b[72] = " *              of x[0] is given in input parameter e0 (i.e., x[0]*2^e0";
static const lxl_str sl7292 = {.p = sl7292b, .len = 71U, .cap = 0U};
static char sl7293b[41] = " *              match x's up to 24 bits.";
static const lxl_str sl7293 = {.p = sl7293b, .len = 40U, .cap = 0U};
static char sl7294b[77] = " *              Example of breaking a double positive z into x[0]+x[1]+x[2]:";
static const lxl_str sl7294 = {.p = sl7294b, .len = 76U, .cap = 0U};
static char sl7295b[41] = " *                      e0 = ilogb(z)-23";
static const lxl_str sl7295 = {.p = sl7295b, .len = 40U, .cap = 0U};
static char sl7296b[43] = " *                      z  = scalbn(z,-e0)";
static const lxl_str sl7296 = {.p = sl7296b, .len = 42U, .cap = 0U};
static char sl7297b[30] = " *              for i = 0,1,2";
static const lxl_str sl7297 = {.p = sl7297b, .len = 29U, .cap = 0U};
static char sl7298b[40] = " *                      x[i] = floor(z)";
static const lxl_str sl7298 = {.p = sl7298b, .len = 39U, .cap = 0U};
static char sl7299b[46] = " *                      z    = (z-x[i])*2**24";
static const lxl_str sl7299 = {.p = sl7299b, .len = 45U, .cap = 0U};
static char sl7300b[70] = " *      y[]     ouput result in an array of double precision numbers.";
static const lxl_str sl7300 = {.p = sl7300b, .len = 69U, .cap = 0U};
static char sl7301b[41] = " *              The dimension of y[] is:";
static const lxl_str sl7301 = {.p = sl7301b, .len = 40U, .cap = 0U};
static char sl7302b[50] = " *                      24-bit  precision       1";
static const lxl_str sl7302 = {.p = sl7302b, .len = 49U, .cap = 0U};
static char sl7303b[50] = " *                      53-bit  precision       2";
static const lxl_str sl7303 = {.p = sl7303b, .len = 49U, .cap = 0U};
static char sl7304b[50] = " *                      64-bit  precision       2";
static const lxl_str sl7304 = {.p = sl7304b, .len = 49U, .cap = 0U};
static char sl7305b[50] = " *                      113-bit precision       3";
static const lxl_str sl7305 = {.p = sl7305b, .len = 49U, .cap = 0U};
static char sl7306b[70] = " *              The actual value is the sum of them. Thus for 113-bit";
static const lxl_str sl7306 = {.p = sl7306b, .len = 69U, .cap = 0U};
static char sl7307b[61] = " *              precison, one may have to do something like:";
static const lxl_str sl7307 = {.p = sl7307b, .len = 60U, .cap = 0U};
static char sl7308b[48] = " *              long double t,w,r_head, r_tail;";
static const lxl_str sl7308 = {.p = sl7308b, .len = 47U, .cap = 0U};
static char sl7309b[59] = " *              t = (long double)y[2] + (long double)y[1];";
static const lxl_str sl7309 = {.p = sl7309b, .len = 58U, .cap = 0U};
static char sl7310b[39] = " *              w = (long double)y[0];";
static const lxl_str sl7310 = {.p = sl7310b, .len = 38U, .cap = 0U};
static char sl7311b[30] = " *              r_head = t+w;";
static const lxl_str sl7311 = {.p = sl7311b, .len = 29U, .cap = 0U};
static char sl7312b[43] = " *              r_tail = w - (r_head - t);";
static const lxl_str sl7312 = {.p = sl7312b, .len = 42U, .cap = 0U};
static char sl7313b[70] = " *      e0      The exponent of x[0]. Must be <= 16360 or you need to";
static const lxl_str sl7313 = {.p = sl7313b, .len = 69U, .cap = 0U};
static char sl7314b[40] = " *              expand the ipio2 table.";
static const lxl_str sl7314 = {.p = sl7314b, .len = 39U, .cap = 0U};
static char sl7315b[33] = " *      nx      dimension of x[]";
static const lxl_str sl7315 = {.p = sl7315b, .len = 32U, .cap = 0U};
static char sl7316b[53] = " *      prec    an integer indicating the precision:";
static const lxl_str sl7316 = {.p = sl7316b, .len = 52U, .cap = 0U};
static char sl7317b[50] = " *                      0       24  bits (single)";
static const lxl_str sl7317 = {.p = sl7317b, .len = 49U, .cap = 0U};
static char sl7318b[50] = " *                      1       53  bits (double)";
static const lxl_str sl7318 = {.p = sl7318b, .len = 49U, .cap = 0U};
static char sl7319b[52] = " *                      2       64  bits (extended)";
static const lxl_str sl7319 = {.p = sl7319b, .len = 51U, .cap = 0U};
static char sl7320b[48] = " *                      3       113 bits (quad)";
static const lxl_str sl7320 = {.p = sl7320b, .len = 47U, .cap = 0U};
static char sl7321b[22] = " * External function:";
static const lxl_str sl7321 = {.p = sl7321b, .len = 21U, .cap = 0U};
static char sl7322b[34] = " *      double scalbn(), floor();";
static const lxl_str sl7322 = {.p = sl7322b, .len = 33U, .cap = 0U};
static char sl7323b[52] = " * Here is the description of some local variables:";
static const lxl_str sl7323 = {.p = sl7323b, .len = 51U, .cap = 0U};
static char sl7324b[70] = " *      jk      jk+1 is the initial number of terms of ipio2[] needed";
static const lxl_str sl7324 = {.p = sl7324b, .len = 69U, .cap = 0U};
static char sl7325b[70] = " *              in the computation. The minimum and recommended value";
static const lxl_str sl7325 = {.p = sl7325b, .len = 69U, .cap = 0U};
static char sl7326b[74] = " *              for jk is 3,4,4,6 for single, double, extended, and quad.";
static const lxl_str sl7326 = {.p = sl7326b, .len = 73U, .cap = 0U};
static char sl7327b[72] = " *              jk+1 must be 2 larger than you might expect so that our";
static const lxl_str sl7327 = {.p = sl7327b, .len = 71U, .cap = 0U};
static char sl7328b[72] = " *              recomputation test works. (Up to 24 bits in the integer";
static const lxl_str sl7328 = {.p = sl7328b, .len = 71U, .cap = 0U};
static char sl7329b[72] = " *              part (the 24 bits of it that we compute) and 23 bits in";
static const lxl_str sl7329 = {.p = sl7329b, .len = 71U, .cap = 0U};
static char sl7330b[71] = " *              the fraction part may be lost to cancelation before we";
static const lxl_str sl7330 = {.p = sl7330b, .len = 70U, .cap = 0U};
static char sl7331b[28] = " *              recompute.)";
static const lxl_str sl7331 = {.p = sl7331b, .len = 27U, .cap = 0U};
static char sl7332b[64] = " *      jz      local integer variable indicating the number of";
static const lxl_str sl7332 = {.p = sl7332b, .len = 63U, .cap = 0U};
static char sl7333b[39] = " *              terms of ipio2[] used.";
static const lxl_str sl7333 = {.p = sl7333b, .len = 38U, .cap = 0U};
static char sl7334b[23] = " *      jx      nx - 1";
static const lxl_str sl7334 = {.p = sl7334b, .len = 22U, .cap = 0U};
static char sl7335b[67] = " *      jv      index for pointing to the suitable ipio2[] for the";
static const lxl_str sl7335 = {.p = sl7335b, .len = 66U, .cap = 0U};
static char sl7336b[49] = " *              computation. In general, we want";
static const lxl_str sl7336 = {.p = sl7336b, .len = 48U, .cap = 0U};
static char sl7337b[64] = " *                      ( 2^e0*x[0] * ipio2[jv-1]*2^(-24jv) )/8";
static const lxl_str sl7337 = {.p = sl7337b, .len = 63U, .cap = 0U};
static char sl7338b[36] = " *              is an integer. Thus";
static const lxl_str sl7338 = {.p = sl7338b, .len = 35U, .cap = 0U};
static char sl7339b[59] = " *                      e0-3-24*jv >= 0 or (e0-3)/24 >= jv";
static const lxl_str sl7339 = {.p = sl7339b, .len = 58U, .cap = 0U};
static char sl7340b[45] = " *              Hence jv = max(0,(e0-3)/24).";
static const lxl_str sl7340 = {.p = sl7340b, .len = 44U, .cap = 0U};
static char sl7341b[71] = " *      jp      jp+1 is the number of terms in PIo2[] needed, jp = jk.";
static const lxl_str sl7341 = {.p = sl7341b, .len = 70U, .cap = 0U};
static char sl7342b[67] = " *      q[]     double array with integral value, representing the";
static const lxl_str sl7342 = {.p = sl7342b, .len = 66U, .cap = 0U};
static char sl7343b[60] = " *              24-bits chunk of the product of x and 2/pi.";
static const lxl_str sl7343 = {.p = sl7343b, .len = 59U, .cap = 0U};
static char sl7344b[66] = " *      q0      the corresponding exponent of q[0]. Note that the";
static const lxl_str sl7344 = {.p = sl7344b, .len = 65U, .cap = 0U};
static char sl7345b[52] = " *              exponent for q[i] would be q0-24*i.";
static const lxl_str sl7345 = {.p = sl7345b, .len = 51U, .cap = 0U};
static char sl7346b[65] = " *      PIo2[]  double precision array, obtained by cutting pi/2";
static const lxl_str sl7346 = {.p = sl7346b, .len = 64U, .cap = 0U};
static char sl7347b[37] = " *              into 24 bits chunks.";
static const lxl_str sl7347 = {.p = sl7347b, .len = 36U, .cap = 0U};
static char sl7348b[42] = " *      f[]     ipio2[] in floating point";
static const lxl_str sl7348 = {.p = sl7348b, .len = 41U, .cap = 0U};
static char sl7349b[67] = " *      iq[]    integer array by breaking up q[] in 24-bits chunk.";
static const lxl_str sl7349 = {.p = sl7349b, .len = 66U, .cap = 0U};
static char sl7350b[61] = " *      fq[]    final product of x*(2/pi) in fq[0],..,fq[jk]";
static const lxl_str sl7350 = {.p = sl7350b, .len = 60U, .cap = 0U};
static char sl7351b[65] = " *      ih      integer. If >0 it indicates q[] is >= 0.5, hence";
static const lxl_str sl7351 = {.p = sl7351b, .len = 64U, .cap = 0U};
static char sl7352b[60] = " *              it also indicates the *sign* of the result.";
static const lxl_str sl7352 = {.p = sl7352b, .len = 59U, .cap = 0U};
static char sl7353b[67] = "static const int init_jk[] = {3,4,4,6}; /* initial value for jk */";
static const lxl_str sl7353 = {.p = sl7353b, .len = 66U, .cap = 0U};
static char sl7354b[69] = " * Table of constants for 2/pi, 396 Hex digits (476 decimal) of 2/pi";
static const lxl_str sl7354 = {.p = sl7354b, .len = 68U, .cap = 0U};
static char sl7355b[70] = " *              integer array, contains the (24*i)-th to (24*i+23)-th";
static const lxl_str sl7355 = {.p = sl7355b, .len = 69U, .cap = 0U};
static char sl7356b[66] = " *              bit of 2/pi after binary point. The corresponding";
static const lxl_str sl7356 = {.p = sl7356b, .len = 65U, .cap = 0U};
static char sl7357b[34] = " *              floating value is";
static const lxl_str sl7357 = {.p = sl7357b, .len = 33U, .cap = 0U};
static char sl7358b[49] = " *                      ipio2[i] * 2^(-24(i+1)).";
static const lxl_str sl7358 = {.p = sl7358b, .len = 48U, .cap = 0U};
static char sl7359b[59] = " * NB: This table must have at least (e0-3)/24 + jk terms.";
static const lxl_str sl7359 = {.p = sl7359b, .len = 58U, .cap = 0U};
static char sl7360b[62] = " *     For quad precision (e0 <= 16360, jk = 6), this is 686.";
static const lxl_str sl7360 = {.p = sl7360b, .len = 61U, .cap = 0U};
